from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class RMOD(SchemaObject):
    productName = SchemaField(name="rmod_basic.product_name")
    productCode = SchemaField(name="rmod_basic.product_code")
    serialNumber = SchemaField(name="rmod_basic.serial_number")
    config_mo_url = SchemaField(name="rmod_basic.config_dn")
    administrative_state = SchemaField(name="state_info.administrative_state")
    availability_status = SchemaField(name="state_info.availability_status")
    operational_state = SchemaField(name="state_info.operational_state")

    def __init__(self, productName, productCode, serialNumber, config_mo_url, administrative_state, availability_status,
                 operational_state):
        """
        :param productName: e.g. AEUD
        :param productCode: e.g. 474611A.X31
        :param serialNumber: e.g. L1190301301
        """
        self.productName = productName
        self.productCode = productCode
        self.serialNumber = serialNumber
        self.administrative_state = administrative_state
        self.availability_status = availability_status
        self.operational_state = operational_state

        super(RMOD, self).__init__()
